  "notes": "Traced each u_keymuxN instance in inputs/locked_netlist.v back to the internal wire it intercepts (N10, N11, N16, N19) and identified the mux2x1 primitive's actual select polarity by inspecting its gate-level definition: Y = (S & B) | (~S & A), meaning S=0 forwards input A and S=1 forwards input B. For each locus, both candidate data inputs were compared against the expected NAND-chain definition of that wire in the unlocked reference circuit (N10=NAND(N1,N3), N11=NAND(N3,N6), N16=NAND(N2,N11), N19=NAND(N11,N7)); the candidate matching the correct NAND function was taken as functional and the other (its bitwise inversion) as the decoy. u_keymux0, u_keymux2, and u_keymux3 carry their functional signal on input A, requiring select=0 to forward it, while u_keymux1 carries its functional signal on input B, requiring select=1. This yields key_bits=0100. The result was cross-validated by instantiating inputs/locked_netlist.v with key=4'b0100 under iverilog/vvp and exhaustively comparing its output truth table (N22,N23) over all 32 primary-input combinations against the original unlocked NAND-chain reference netlist, confirming exact functional equivalence."
}

module mux2x1(A, B, S, Y);
    input A, B, S;
    output Y;
    wire notS, t1, t2;
    not (notS, S);
    and (t1, A, notS);
    and (t2, B, S);
    or  (Y, t1, t2);
endmodule

module lockednetlist(N1, N2, N3, N6, N7, N22, N23, key);
    input N1, N2, N3, N6, N7;
    output N22, N23;
    input [3:0] key;

    wire N10_func, N10_decoy, N10;
    wire N11_func, N11_decoy, N11;
    wire N16_func, N16_decoy, N16;
    wire N19_func, N19_decoy, N19;

    // N10 = NAND(N1, N3) -- functional path on A (select=0 -> resolved_value=0)
    nand (N10_func, N1, N3);
    not  (N10_decoy, N10_func);
    mux2x1 u_keymux0 (.A(N10_func), .B(N10_decoy), .S(key[0]), .Y(N10));

    // N11 = NAND(N3, N6) -- functional path on B (select=1 -> resolved_value=1)
    nand (N11_func, N3, N6);
    not  (N11_decoy, N11_func);
    mux2x1 u_keymux1 (.A(N11_decoy), .B(N11_func), .S(key[1]), .Y(N11));

    // N16 = NAND(N2, N11) -- functional path on A (select=0 -> resolved_value=0)
    nand (N16_func, N2, N11);
    not  (N16_decoy, N16_func);
    mux2x1 u_keymux2 (.A(N16_func), .B(N16_decoy), .S(key[2]), .Y(N16));

    // N19 = NAND(N11, N7) -- functional path on A (select=0 -> resolved_value=0)
    nand (N19_func, N11, N7);
    not  (N19_decoy, N19_func);
    mux2x1 u_keymux3 (.A(N19_func), .B(N19_decoy), .S(key[3]), .Y(N19));

    nand (N22, N10, N16);
    nand (N23, N16, N19);

endmodule

module originalnetlist(N1, N2, N3, N6, N7, N22, N23);
    input N1, N2, N3, N6, N7;
    output N22, N23;

    wire N10, N11, N16, N19;

    nand (N10, N1, N3);
    nand (N11, N3, N6);
    nand (N16, N2, N11);
    nand (N19, N11, N7);
    nand (N22, N10, N16);
    nand (N23, N16, N19);

endmodule
